CREATE OR REPLACE FUNCTION get_match_risk_profile(p_match_id text)
RETURNS json AS $$
    SELECT to_json(r)
    FROM (
        SELECT *
        FROM risk_evaluation
        WHERE risk_eval_registry = p_match_id
    ) r;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION get_match_risk_profile(p_match_id text)
RETURNS jsonb AS $$
    SELECT json_object_agg(key, value)
    FROM (
        SELECT key, value
        FROM jsonb_each(to_jsonb(
            (SELECT row_to_json(r) FROM (SELECT * FROM risk_evaluation WHERE risk_eval_registry = p_match_id) r)
        ))
    ) t;
$$ LANGUAGE sql;

CREATE OR REPLACE FUNCTION get_match_risk_profile(p_match_id text)
RETURNS TABLE(match_data jsonb) AS $$
BEGIN
    RETURN QUERY SELECT row_to_json(r)::jsonb FROM (SELECT * FROM risk_evaluation WHERE risk_eval_registry = p_match_id) r;
END;
$$ LANGUAGE plpgsql;

